  1483  /*
  1484   * pkcs 15 needs to find the cert matching the keys to fill in some of the fields that wasn't stored
  1485   * with the key. To do this we need to look for the cert matching the key's CKA_ID. For flexibility,
  1486   * We simply search using a pkcs #11 style template using the cardctl_coolkey_attribute_t structure */
  1487  sc_cardctl_coolkey_object_t *
  1488  coolkey_find_object_by_template(sc_card_t *card, sc_cardctl_coolkey_attribute_t *template, int count)
  1489  {
  1490          list_t *list;
  1491          sc_cardctl_coolkey_object_t *current, *rv = NULL;
  1492          coolkey_private_data_t * priv = COOLKEY_DATA(card);
  1493          int i, r;
  1494          unsigned int tmp_pos = (unsigned int) -1;
  1495
  1496          list = &priv->objects_list;
  1497          if (list->iter_active) {
  1498                  /* workaround missing functionality of second iterator */
  1499                  tmp_pos = list->iter_pos;
  1500                  list_iterator_stop(list);
  1501          }
  1502
  1503          list_iterator_start(list);
  1504          while (list_iterator_hasnext(list)) {
  1505                  sc_cardctl_coolkey_attribute_t attribute;
  1506                  current = list_iterator_next(list);
  1507                  attribute.object = current;
  1508
  1509                  for (i=0; i < count; i++) {
  1510                          attribute.attribute_type = template[i].attribute_type;
  1511                          r = coolkey_find_attribute(card, &attribute);
  1512                          if (r < 0) {
  1513                                  break;
  1514                          }
  1515                          if (template[i].attribute_data_type != attribute.attribute_data_type) {
  1516                                  break;
  1517                          }
  1518                          if (template[i].attribute_length != attribute.attribute_length) {
  1519                                  break;
  1520                          }
  1521                          if (memcmp(attribute.attribute_value, template[i].attribute_value,
  1522                                                          attribute.attribute_length) != 0) {
  1523                                  break;
  1524                          }
  1525                  }
  1526                  /* just return the first one */
  1527                  if (i == count) {
  1528                          rv = current;
  1529                          break;
  1530                  }
  1531          }
  1532
  1533          list_iterator_stop(list);
  1534          if (tmp_pos != (unsigned int)-1) {
  1535                  /* workaround missing functionality of second iterator */
  1536                  list_iterator_start(list);
  1537                  while (list_iterator_hasnext(list) && list->iter_pos < tmp_pos)
  1538                          (void) list_iterator_next(list);
  1539          }
  1540          return rv;

