  2146          r = coolkey_list_object(card, COOLKEY_LIST_RESET, &object_info);
  2147          while (r >= 0) {
  2148                  unsigned long object_id;
  2149                  unsigned short object_len;
  2150
  2151                  /* The card did not return what we expected: Lets try other objects */
  2152                  if ((size_t)r < (sizeof(object_info)))
  2153                          break;
  2154
  2155                  /* TODO also look at the ACL... */
  2156
  2157                  object_id = bebytes2ulong(object_info.object_id);
  2158                  object_len = bebytes2ulong(object_info.object_length);
  2159
  2160
  2161                  /* the combined object is a single object that can store the other objects.
  2162                   * most coolkeys provisioned by TPS has a single combined object that is
  2163                   * compressed greatly increasing the effectiveness of compress (since lots
  2164                   * of certs on the token share the same Subject and Issuer DN's). We now
  2165                   * process it separately so that we can have both combined objects managed
